// Auftrag prüfen (Stefan 18.10.2026): genau ein Auftrag je Aufruf. aktion ablegen {talent_id, kampagne_id, art, name, erstellt_von, Binärfeld datei},
// holen {datei_id}, keine (nichts zu tun, für Mail-Entwürfe ohne Anhang). Misst die Dateigröße für die Grenze des Dienstes (OneDrive 4 MB).
// loeschen {datei: {dienst, extern_id, pfad}} (Stefan 18.10.2026, Vertrag Migration 51 §6.4): Dateien gelöschter Talents, Aufruf aus TALENTS 4.
const items = $input.all();
if (items.length !== 1) throw new Error('TALENTS Ablage erwartet genau einen Auftrag je Aufruf (bitte im Modus "für jedes Element" aufrufen).');
const j = items[0].json || {};
const aktion = String(j.aktion || '').trim();
if (!['ablegen', 'holen', 'keine', 'loeschen'].includes(aktion)) throw new Error('Unbekannte Aktion für TALENTS Ablage: ' + aktion);
const aus = { aktion, talent_id: j.talent_id ?? null, kampagne_id: j.kampagne_id ?? null, art: String(j.art || ''), name: String(j.name || ''),
  erstellt_von: String(j.erstellt_von || ''), datei_id: j.datei_id ?? null, bytes: null, mime: null };
if (aktion === 'loeschen') {
  const d = j.datei && typeof j.datei === 'object' ? j.datei : {};
  aus.datei = { dienst: String(d.dienst || '').trim(), extern_id: d.extern_id == null ? '' : String(d.extern_id).trim(), pfad: String(d.pfad || '').trim() };
}
let binary;
if (aktion === 'ablegen') {
  const b = items[0].binary && (items[0].binary.datei || items[0].binary.data);
  if (!b) throw new Error('Keine Datei zum Ablegen übergeben (Binärfeld "datei").');
  const buf = await this.helpers.getBinaryDataBuffer(0, items[0].binary.datei ? 'datei' : 'data');
  aus.bytes = buf.length;
  aus.mime = String(b.mimeType || 'application/pdf');
  if (!aus.name) aus.name = String(b.fileName || 'Datei.pdf');
  binary = { datei: b };
}
return [{ json: aus, binary }];

// Plan prüfen (Stefan 18.10.2026): nächster Schritt aus talents_ablage_plan(): Fehler, Ordner anlegen (je Durchlauf einer) oder hochladen.
const a = $('Auftrag prüfen').first();
const p = $input.first().json.p || {};
if (p.ok !== true) return [{ json: { weg: 'fehler', fehler: String(p.fehler || 'Der Speicherort ist nicht bereit.') } }];
if (!p.fehlend && p.max_bytes && Number(a.json.bytes) > Number(p.max_bytes))
  return [{ json: { weg: 'fehler', fehler: 'Die Datei ist größer als 4 MB. ' + p.dienst_name + ' nimmt über Ally nur Dateien bis 4 MB an (Grenze des n8n-Bausteins). Die Datei steht auf der Oberfläche zum Herunterladen bereit.' } }];
// Kennzeichen ablage_eingabe (Stefan 18.10.2026): nur in der Eingabe der Cloud-Bausteine. Ein ausgeschalteter Baustein gibt seine Eingabe unverändert
// weiter; Ordner-Kennung und Datei-Kennung melden dann "Speicherort ... ist noch nicht eingerichtet" statt eines Erfolgs.
return [{ json: Object.assign({}, p, { weg: p.fehlend ? 'ordner' : 'hochladen' }, p.dienst === 'ally' ? {} : { ablage_eingabe: true }), binary: a.binary }];

// Ordner-Kennung (Stefan 18.10.2026): Kennung des neu angelegten Ordners je Dienst. Dropbox meldet bei vorhandenem Ordner einen Konflikt:
// dann gilt der angefragte Pfad.
const p = $('Plan prüfen').first().json;
const f = p.fehlend || {};
const j = $input.first().json || {};
// Speicherort ohne Zugang (Stefan 18.10.2026): Cloud-Baustein ausgeschaltet (gibt seine Eingabe mit dem Kennzeichen ablage_eingabe unverändert weiter)
// oder ohne Zugang in n8n. Nie als Erfolg werten.
if (j.ablage_eingabe === true || /does not have any credentials|credentials not found/i.test(JSON.stringify(j.error || ''))) return [{ json: { ok: false, fehler: 'Speicherort ' + p.dienst_name + ' ist noch nicht eingerichtet.' } }];
const fehler = j.error ? String(j.error.message || j.error.description || j.error) : '';
let id = '';
if (fehler) {
  if (p.dienst === 'dropbox' && /conflict|already exists|existiert/i.test(fehler)) id = String(f.pfad || '');
  else return [{ json: { ok: false, fehler: 'Der Ordner „' + f.name + '“ konnte in ' + p.dienst_name + ' nicht angelegt werden: ' + fehler.slice(0, 200) } }];
} else if (p.dienst === 'dropbox') {
  id = String((j.metadata && j.metadata.path_display) || f.pfad || '');
} else {
  id = String(j.id || (j.body && j.body.id) || '');
}
if (!id) return [{ json: { ok: false, fehler: 'Der Ordner „' + f.name + '“ wurde angelegt, aber ohne Kennung zurückgemeldet.' } }];
return [{ json: { ok: true, dienst: p.dienst, schluessel: f.schluessel, extern_id: id, pfad: f.pfad } }];

// Ablegen im Speicherort von Ally über SPEICHER 1 (Bereich ally, Pfad aus dem Plan)
const p = $input.first();
return [{ json: { aktion: 'ablegen', bereich: p.json.ally_bereich || 'ally', pfad: p.json.ally_pfad, ueberschreiben: true }, binary: p.binary }];

// Datei-Kennung (Stefan 18.10.2026): Kennung und Link der hochgeladenen Datei je Dienst, für talents_ablage_datei_merken
const p = $('Plan prüfen').first().json;
const a = $('Auftrag prüfen').first().json;
const j = $input.first().json || {};
// Speicherort ohne Zugang (Stefan 18.10.2026): Cloud-Baustein ausgeschaltet (gibt seine Eingabe mit dem Kennzeichen ablage_eingabe unverändert weiter)
// oder ohne Zugang in n8n. Nie als Erfolg werten.
if (p.dienst !== 'ally' && (j.ablage_eingabe === true || j.nicht_eingerichtet === true || /does not have any credentials|credentials not found/i.test(JSON.stringify(j.error || ''))))
  return [{ json: { ok: false, fehler: 'Speicherort ' + p.dienst_name + ' ist noch nicht eingerichtet.' } }];
// Speicherort von Ally (Stefan 18.10.2026): nur ok:true von SPEICHER 1 ist Erfolg. Bricht SPEICHER 1 ab, gibt n8n die Eingabe ohne ok weiter.
if (p.dienst === 'ally' && j.ok !== true && !j.error && !j.fehler) return [{ json: { ok: false, fehler: 'Speicherort Ally hat nicht geantwortet.' } }];
const fehler = j.error ? String(j.error.message || j.error.description || j.error) : (p.dienst === 'ally' && j.ok !== true ? String(j.fehler || 'unbekannt') : '');
if (fehler) return [{ json: { ok: false, fehler: 'Die Datei konnte nicht in ' + p.dienst_name + ' abgelegt werden: ' + fehler.slice(0, 200) } }];
let extern_id = null, url = null, pfad;
if (p.dienst === 'ally') { pfad = p.ally_pfad; }
else {
  pfad = p.ziel_pfad + '/' + p.dateiname;
  if (p.dienst === 'dropbox') { extern_id = String(j.path_display || p.dropbox_pfad || ''); }
  else { extern_id = String(j.id || ''); url = j.webViewLink || j.webUrl || null; }
  if (!extern_id) return [{ json: { ok: false, fehler: 'Die Datei wurde hochgeladen, aber ohne Kennung zurückgemeldet.' } }];
}
return [{ json: { ok: true, daten: { talent_id: a.talent_id, kampagne_id: a.kampagne_id, art: a.art, name: p.dateiname, dienst: p.dienst, pfad,
  extern_id, extern_ordner: p.dienst === 'sharepoint' ? p.ziel_id : null, extern_url: url, bytes: a.bytes, mime: a.mime, erstellt_von: a.erstellt_von } } }];

// Fehler (Stefan 18.10.2026): Rückgabe an den Aufrufer, ohne Abbruch
const j = $input.first().json || {};
return [{ json: { ok: false, fehler: String(j.fehler || 'Unbekannter Fehler im Speicherort.') } }];

// Ergebnis (Stefan 18.10.2026): Rückgabe an den Aufrufer
const r = $input.first().json.r || {};
const p = $('Plan prüfen').first().json;
if (r.ok !== true) return [{ json: { ok: false, fehler: String(r.fehler || 'Die Datei konnte nicht gemerkt werden.') } }];
return [{ json: { ok: true, datei_id: r.datei_id, name: p.dateiname, dienst: p.dienst, ort: p.dienst_name } }];

// Holen prüfen (Stefan 18.10.2026): wo die Datei liegt (talents_ablage_holen); bei Ally-Speicherort Auftrag für SPEICHER 1
const r = $input.first().json.r || {};
if (r.ok !== true) return [{ json: { weg: 'fehler', fehler: String(r.fehler || 'Diese Datei gibt es nicht.') } }];
if (r.eingerichtet !== true) return [{ json: { weg: 'fehler', fehler: 'Der Speicherort dieser Datei ist nicht mehr eingerichtet.' } }];
// Kennzeichen ablage_eingabe (Stefan 18.10.2026): nur für Cloud-Dienste, erkennt einen ausgeschalteten Baustein in "Ergebnis holen".
return [{ json: Object.assign({}, r, { weg: r.dienst, aktion: 'holen', bereich: r.ally_bereich || 'ally' }, r.dienst === 'ally' ? {} : { ablage_eingabe: true }) }];

// Ergebnis holen (Stefan 18.10.2026): Datei immer im Binärfeld "datei" zurückgeben
const d = $('Holen prüfen').first().json;
const it = $input.first();
const j = it.json || {};
const b = it.binary && (it.binary.datei || it.binary.data);
// Speicherort ohne Zugang (Stefan 18.10.2026): Cloud-Baustein ausgeschaltet (gibt seine Eingabe mit dem Kennzeichen ablage_eingabe unverändert weiter)
// oder ohne Zugang in n8n. Nie als Erfolg werten.
const DIENST = { google_drive: 'Google Drive', onedrive: 'OneDrive', sharepoint: 'SharePoint', dropbox: 'Dropbox' };
if (d.weg !== 'ally' && (j.ablage_eingabe === true || /does not have any credentials|credentials not found/i.test(JSON.stringify(j.error || ''))))
  return [{ json: { ok: false, datei_id: d.datei_id, fehler: 'Speicherort ' + (d.dienst_name || DIENST[d.weg] || d.weg) + ' ist noch nicht eingerichtet.' } }];
// Speicherort von Ally (Stefan 18.10.2026): nur ok:true von SPEICHER 1 ist Erfolg. Bricht SPEICHER 1 ab, gibt n8n die Eingabe ohne ok weiter.
// Die zurückgegebene Eingabe aus "Holen prüfen" enthält weg und ok:true; SPEICHER 1 liefert nie das Feld weg.
if (d.weg === 'ally' && (j.weg !== undefined || (j.ok !== true && !j.error && !j.fehler))) return [{ json: { ok: false, datei_id: d.datei_id, fehler: 'Speicherort Ally hat nicht geantwortet.' } }];
if (j.error || j.ok === false || (d.weg === 'ally' && j.ok !== true) || !b) return [{ json: { ok: false, datei_id: d.datei_id, fehler: 'Die Datei „' + d.name + '“ konnte nicht geholt werden: ' + String((j.error && (j.error.message || j.error)) || j.fehler || 'keine Daten').slice(0, 200) } }];
b.fileName = d.name;
b.mimeType = d.mime || b.mimeType;
return [{ json: { ok: true, datei_id: d.datei_id, name: d.name, mime: d.mime }, binary: { datei: b } }];

// Fehler (Stefan 18.10.2026): Rückgabe an den Aufrufer, ohne Abbruch
const j = $input.first().json || {};
return [{ json: { ok: false, fehler: String(j.fehler || 'Unbekannter Fehler im Speicherort.') } }];

// Google Drive (Stefan 18.10.2026): Upload-Adresse aus der Antwort (Header location) und Datei aus dem Plan für das Hochladen
const p = $('Plan prüfen').first();
const j = $input.first().json || {};
// Speicherort ohne Zugang (Stefan 18.10.2026): Cloud-Baustein ausgeschaltet (gibt seine Eingabe mit dem Kennzeichen ablage_eingabe unverändert weiter)
// oder ohne Zugang in n8n. Nie als Erfolg werten.
if (j.ablage_eingabe === true || /does not have any credentials|credentials not found/i.test(JSON.stringify(j.error || ''))) return [{ json: { ok: false, nicht_eingerichtet: true, error: { message: 'Speicherort ' + p.json.dienst_name + ' ist noch nicht eingerichtet.' } } }];
const url = String((j.headers && (j.headers.location || j.headers.Location)) || '');
if (j.error || !url.startsWith('https://')) return [{ json: { ok: false, error: { message: String((j.error && (j.error.message || j.error)) || 'Google Drive hat keine Upload-Adresse geliefert.') } } }];
// Kennzeichen ablage_eingabe (Stefan 18.10.2026): erkennt einen ausgeschalteten Baustein "Hochladen Google Drive" in der Datei-Kennung.
return [{ json: { ok: true, url, ablage_eingabe: true }, binary: p.binary }];

// Löschen planen (Stefan 18.10.2026, Vertrag Migration 51 §6.4): Weg je Speicherort. Kennungen nur im erwarteten Format, sonst Fehler ohne Löschversuch.
// Speicherort von Ally über SPEICHER 1 (Bereich ally, relativer Pfad); Cloud-Dienste nur, solange sie in Ally eingerichtet sind.
const a = $('Auftrag prüfen').first().json;
const d = a.datei || {};
const x = ($input.first().json || {}).d;
const NAME = { ally: 'Speicherort von Ally', google_drive: 'Google Drive', onedrive: 'OneDrive', sharepoint: 'SharePoint', dropbox: 'Dropbox' };
const f = t => [{ json: { weg: 'fehler', fehler: t } }];
// Kennzeichen ablage_eingabe (Stefan 18.10.2026): nur für Cloud-Dienste, erkennt einen ausgeschalteten Baustein im Löschergebnis.
if (!NAME[d.dienst]) return f('Unbekannter Speicherort: ' + String(d.dienst || '').slice(0, 40));
if (d.dienst === 'ally') {
  const p = String(d.pfad || '');
  if (!p || p.length > 1000 || p.startsWith('/') || p.split('/').some(t => t === '' || t === '.' || t === '..')) return f('Der Pfad im Speicherort von Ally fehlt oder ist ungültig.');
  return [{ json: { weg: 'ally', aktion: 'loeschen', bereich: 'ally', pfad: p } }];
}
if (!x || typeof x !== 'object') return f(NAME[d.dienst] + ' ist in Ally nicht mehr eingerichtet. Bitte die Datei dort selbst löschen.');
const id = String(d.extern_id || '');
if (d.dienst === 'dropbox') {
  if (!(id.startsWith('/') || id.startsWith('id:')) || id.length > 1000) return f('Der Dropbox-Pfad der Datei fehlt.');
  return [{ json: { weg: 'dropbox', dropbox_pfad: id, ablage_eingabe: true } }];
}
if (!/^[A-Za-z0-9!._-]{1,300}$/.test(id)) return f('Die Kennung der Datei in ' + NAME[d.dienst] + ' fehlt oder ist ungültig.');
if (d.dienst === 'sharepoint') {
  const s = String(x.site_id || '');
  if (!s || s.length > 300) return f('Die SharePoint-Website ist nicht eingerichtet.');
  return [{ json: { weg: 'sharepoint', extern_id: id, site_id: s, ablage_eingabe: true } }];
}
return [{ json: { weg: d.dienst, extern_id: id, ablage_eingabe: true } }];

// Löschergebnis (Stefan 18.10.2026, Vertrag Migration 51 §6.4): Rückgabe an den Aufrufer {ok, fehlt, fehler}; fehlt = Datei gab es nicht (mehr).
// Google Drive files.update mit trashed=true (Papierkorb, 30 Tage); Microsoft Graph DELETE driveItem: 204 No Content (Papierkorb der Website bzw. von OneDrive).
// 404 gilt als "nicht vorhanden" (Fehlertexte der Dienste nicht geprüft). Dropbox (n8n-Baustein, files/delete_v2): Erfolg = metadata, Fehlertext mit
// not_found = nicht vorhanden (Text nicht geprüft). SPEICHER 1: ok mit vorhanden true/false.
const p = $('Löschen planen').first().json;
const j = $input.first().json || {};
const NAME = { ally: 'im Speicherort von Ally', google_drive: 'in Google Drive', onedrive: 'in OneDrive', sharepoint: 'in SharePoint', dropbox: 'in Dropbox' };
const text = v => String(v == null ? '' : (typeof v === 'object' ? (v.message || v.description || v.code || JSON.stringify(v)) : v)).replace(/\s+/g, ' ').trim().slice(0, 200);
const aus = x => [{ json: Object.assign({ ok: false, fehlt: false, fehler: null }, x) }];
if (p.weg === 'fehler') return aus({ fehler: String(p.fehler || 'Unbekannter Fehler.') });
const ort = NAME[p.weg] || String(p.weg);
if (p.weg === 'ally') {
  if (j.ok === true) return j.vorhanden === false ? aus({ ok: true, fehlt: true }) : aus({ ok: true });
  // Ohne Antwort von SPEICHER 1 (Abbruch: n8n gibt die Eingabe ohne ok weiter) eigene Meldung (Stefan 18.10.2026)
  if (!j.fehler && !j.error) return aus({ fehler: 'Speicherort Ally hat nicht geantwortet.' });
  return aus({ fehler: 'Löschen ' + ort + ' fehlgeschlagen: ' + text(j.fehler || j.error || 'unbekannt') });
}
// Speicherort ohne Zugang (Stefan 18.10.2026): Cloud-Baustein ausgeschaltet (gibt seine Eingabe mit dem Kennzeichen ablage_eingabe unverändert weiter)
// oder ohne Zugang in n8n. Nie als Erfolg werten.
const DIENST = { google_drive: 'Google Drive', onedrive: 'OneDrive', sharepoint: 'SharePoint', dropbox: 'Dropbox' };
if (j.ablage_eingabe === true || /does not have any credentials|credentials not found/i.test(JSON.stringify(j.error || ''))) return aus({ fehler: 'Speicherort ' + (DIENST[p.weg] || p.weg) + ' ist noch nicht eingerichtet.' });
if (p.weg === 'dropbox') {
  if (j.metadata) return aus({ ok: true });
  const t = text(j.error || j.message || 'unbekannt');
  if (/not_found/i.test(t)) return aus({ ok: true, fehlt: true });
  return aus({ fehler: 'Löschen ' + ort + ' fehlgeschlagen: ' + t });
}
const status = Number(j.statusCode) || 0;
if (status >= 200 && status < 300) return aus({ ok: true });
if (status === 404) return aus({ ok: true, fehlt: true });
let b = j.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
const e = b && typeof b === 'object' && b.error ? b.error : j.error;
return aus({ fehler: 'Löschen ' + ort + ' fehlgeschlagen: ' + (status ? 'HTTP ' + status + (e ? ' (' + text(e) + ')' : '') : text(e || 'nicht erreichbar')) });
